using Godot;
using Godot.Collections; // Required for Dictionary

// Define an enum for the resource types
public enum ResourceType
{
    Food,
    Ore,
    Money,
    ShipyardProduction,
}

public static class ResourceTypeExtensions
{
    /// <summary>
    /// Returns true if the resource accumulates in global empire stockpiles and is generated by base population.
    /// Non-stockpileable resources (such as ShipyardProduction) act as local per-tick capacity only.
    /// </summary>
    public static bool IsStockpileable(this ResourceType type) => type switch
    {
        ResourceType.ShipyardProduction => false,
        _ => true,
    };
}

// This makes your custom resource type available in the Godot editor
[GlobalClass]
public partial class ImprovementResource : Resource
{
    // [Export] allows you to define and edit this list directly in the Godot Inspector
    [Export]
    public string ImprovementName { get; set; }

    [Export]
    public string ImprovementDescription { get; set; }

    [Export]
    public int BuildTime { get; set; }

    // Use a Dictionary to store resource outputs
    [Export]
    public Dictionary<ResourceType, int> ResourceOutput { get; set; } =
        new Dictionary<ResourceType, int>();

    // Use a Dictionary to store build costs
    [Export]
    public Dictionary<ResourceType, int> BuildCost { get; set; } =
        new Dictionary<ResourceType, int>();
}
